 function _isPortOpen(host, port, timeout) {
 var socket = null;
 try {
 // 解析主机地址
 var address = InetAddress.getByName(host);
 // 尝试建立连接
 socket = new Socket(address, port);
 // 设置超时时间
 socket.setSoTimeout(timeout);
 // 连接成功，端口打开
 return true;
 } catch (e) {
 // 捕获异常：连接失败，端口关闭或不可达
 return false;
 }
 finally {
 // 确保关闭socket
 if (socket !== null) {
 try {
 socket.close();
 } catch (ignore) {
 // 忽略关闭时的异常
 }
 }
 }
 }
